# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _require_email(student: Student) -> str:
    if not student.email:
        raise ProjectError(
            f"no email for {student.display_name}"
        )
    return student.email

def _cells(student: Student) -> Tuple[str, str, str]:
    return (
        student.display_name,
        student.section,
        _require_email(student)
    )

def _line(row: Tuple[str, ...], widths: List[int]) -> str:
    cells = [c.ljust(w) for c, w in zip(row, widths)]
    return "  ".join(cells).rstrip()

# ---
def contact_rows(students: List[Student]) -> List[str]:
    if not students:
        raise ProjectError("no students given")
    ordered = sorted(students, key=_cells)
    rows = [_cells(item) for item in ordered]
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [_line(row, widths) for row in rows]
EOF
cat > tests/test_contacts.py <<'EOF'
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

def _student(last, section, email="a@x.org"):
    return Student("1", last, "Pat", section, email)

class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _student("Zed", "B", "z@x.org"),
            _student("Longname", "A", "l@x.org")
        ])
        self.assertEqual(rows, [
            "Longname, Pat  A  l@x.org",
            "Zed, Pat       B  z@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([_student("Zed", "B", None)])
        self.assertIn("Zed, Pat", str(ctx.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
EOF
